def transform(grid):
    h, w = len(grid), len(grid[0])
    from collections import Counter

    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    fg = next((v for row in grid for v in row if v != bg), bg)

    # Find horizontal bands containing the non-background pattern.
    active = [any(v == fg for v in row) for row in grid]
    bands = []
    r = 0
    while r < h:
        if not active[r]:
            r += 1
            continue
        start = r
        while r < h and active[r]:
            r += 1
        bands.append((start, r))

    out = [row[:] for row in grid]
    if len(bands) < 2:
        return out

    (top, top_end), (lower, lower_end) = bands[:2]
    rows = min(top_end - top, lower_end - lower)
    diff = [
        [grid[lower + dr][c] == fg and grid[top + dr][c] == bg
         for c in range(w)]
        for dr in range(rows)
    ]

    # Find the largest solid rectangle present in the lower band but absent
    # from the corresponding location in the upper band.
    best = None
    for r1 in range(rows):
        for r2 in range(r1, rows):
            for c1 in range(w):
                for c2 in range(c1, w):
                    if all(diff[rr][cc]
                           for rr in range(r1, r2 + 1)
                           for cc in range(c1, c2 + 1)):
                        area = (r2 - r1 + 1) * (c2 - c1 + 1)
                        if best is None or area > best[0]:
                            best = (area, r1, r2, c1, c2)

    if best:
        _, r1, r2, c1, c2 = best
        for rr in range(r1, r2 + 1):
            for cc in range(c1, c2 + 1):
                out[top + rr][cc] = 1

    return out
